+        private static char GetFileTypeChar(ISftpFile entry)
+        {
+            if (entry.IsSymbolicLink) return 'l';
+            if (entry.IsDirectory) return 'd';
+            if (entry.IsBlockDevice) return 'b';
+            if (entry.IsCharacterDevice) return 'c';
